const session = global.get("parat_bridge.ropc_session");
const source = msg.metadata.source;
const incidentId = source.client_specific?.incident_id;

// Rewrite notification text
const clientName = source.client_system || "Ukjent";
const logName = source.name || source.client_specific?.log_name || "Ukjent";
msg.payload.text = "[" + clientName + " - " + logName + "] oppdaterte kartet på deres ende";    

if (!session || !session.enrichedToken || !incidentId) {
    node.warn("[BOOST] Cannot fetch geo — no session or incident_id");
    return [null, msg];
}

// Save entry before HTTP request overwrites payload
msg._original_entry = msg.payload;

msg.url = session.apiUrl + "/restapi/incidents/"
    + incidentId + "/periodic/" + session.userId;
msg.headers = { "Authorization": "Bearer " + session.enrichedToken };

return [msg, null];

const incident = msg.payload;
const rawFeatures = incident?.mapFeatures;
const source = msg.metadata.source;
const connKey = "parat_bridge.connections." + msg.metadata.connection_name
    + ".clients." + source.identifier + ".client_specific";

// Parse mapFeatures
let features = null;
if (rawFeatures) {
    try {
        const parsed = JSON.parse(rawFeatures);
        if (Array.isArray(parsed)) {
            // Legacy format → normalize to GeoJSON FeatureCollection
            features = parsed.map(item => {
                const lit = item.literal;
                let geometry;
                if (lit.type === "circle") {
                    geometry = { type: "Point", coordinates: [lit.center.lng, lit.center.lat] };
                } else if (lit.type === "rectangle") {
                    const b = lit.bounds;
                    geometry = {
                        type: "Polygon",
                        coordinates: [[
                            [b.west, b.south], [b.east, b.south],
                            [b.east, b.north], [b.west, b.north],
                            [b.west, b.south]
                        ]]
                    };
                }
                return {
                    id: item.id,
                    name: item.name || "",
                    color: lit.fillColor || "#337ab7",
                    geometry: geometry,
                    radius: lit.type === "circle" ? lit.radius : undefined
                };
            });
        } else if (parsed.type === "FeatureCollection") {
            features = parsed.features.map(f => ({
                id: f.id,
                name: f.properties?.name || "",
                color: f.properties?.color || "#337ab7",
                geometry: f.geometry,
                isCircle: f.properties?.isCircle || false,
                isRectangle: f.properties?.isRectangle || false
            }));
        }
    } catch (e) {
        node.warn("[BOOST] Failed to parse mapFeatures: " + e.message);
    }
}

// Diff against last known
const lastFeatures = global.get(connKey + ".last_map_features") || [];
const lastIds = new Set(lastFeatures.map(f => f.id));
const currentIds = new Set((features || []).map(f => f.id));

const added = (features || []).filter(f => !lastIds.has(f.id));
const removed = lastFeatures.filter(f => !currentIds.has(f.id));
const kept = (features || []).filter(f => lastIds.has(f.id));
const changed = kept.filter(f => {
    const old = lastFeatures.find(o => o.id === f.id);
    return JSON.stringify(old) !== JSON.stringify(f);
});

// Store current state
global.set(connKey + ".last_map_features", features || []);

// Restore original entry as payload
msg.payload = msg._original_entry;
delete msg._original_entry;

if (added.length === 0 && removed.length === 0 && changed.length === 0) {
    return msg;
}

msg.metadata.geo = {
    type: "mapFeatures",
    added: added,
    removed: removed,
    changed: changed,
    all: features
};

node.status({
    fill: "green", shape: "dot",
    text: "+" + added.length + " -" + removed.length
        + " ~" + changed.length + " " + new Date().toLocaleTimeString()
});

return msg;
